		/** 
		 * Tests creating a new Advertiser.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Advertiser");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Advertiser" );

			try {            
				Advertiser entity = AdvertiserService.getAdvertiserInstance().createAdvertiser( generateNewEntity() );
				thePrimaryKey = entity.getAdvertiserId();
				LOGGER.info( "-- Successfully created a Advertiser with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Advertiser. 
		 */
		public Advertiser testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Advertiser" );

			Advertiser entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Advertiser with primary key" );
			msg.append( thePrimaryKey );
			
			AdvertiserFetchOneSummary fetchOneSummary = new AdvertiserFetchOneSummary( thePrimaryKey );

			try {
				entity = AdvertiserService.getAdvertiserInstance().getAdvertiser( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Advertiser " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Advertiser.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Advertiser." );

			StringBuilder msg = new StringBuilder( "Failed to update a Advertiser : " );        
			Advertiser entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Advertiser." );

				// for use later on...
				thePrimaryKey = entity.getAdvertiserId();

				AdvertiserService proxy = AdvertiserService.getAdvertiserInstance();            
				proxy.updateAdvertiser( entity );   

				LOGGER.info( "-- Successfully saved Advertiser - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Advertiser.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Advertiser." );

			try{
			    Advertiser entity = testRead(); 
				AdvertiserService.getAdvertiserInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Advertiser with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Advertiser with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Advertisers.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Advertisers:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Advertiser : " );        
			List<Advertiser> collection  = null;

			try {
				// call the static get method on the AdvertiserService
				collection = AdvertiserService.getAdvertiserInstance().getAllAdvertiser();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Advertiser entity = null;            
					Iterator<Advertiser> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getAdvertiserId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

